function coreReportStyles(){const s=document.createElement('style');s.textContent='.core-actions{display:flex;gap:8px}.core-actions button:last-child{background:#3f5a80}.core-hero{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:16px}.core-hero>div{padding:18px;border-radius:16px;background:linear-gradient(145deg,#173b6c,#24578d);color:#fff;box-shadow:0 10px 28px #173b6c24}.core-hero span,.core-hero small{display:block;opacity:.78}.core-hero strong{display:block;font-size:25px;margin:5px 0}.core-alerts{display:grid;gap:9px}.core-alert{display:flex;gap:13px;padding:13px;border:1px solid #e0e7ef;border-radius:12px;background:#fbfcfe}.core-alert i{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#173b6c;color:#fff;font-style:normal;font-weight:700}.core-alert p{margin:3px 0}.core-alert small{color:#718096}.core-two{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:16px 0}@media(max-width:850px){.core-hero,.core-two{grid-template-columns:1fr}}@media print{body.print-core .dash-side,body.print-core .dash-top,body.print-core .dash-filter,body.print-core .dash-view:not([data-page=core]),body.print-core .core-actions{display:none!important}body.print-core .investment-shell{display:block}body.print-core .dash-main{margin:0}body.print-core #dashViewcore{display:block!important}body.print-core .dash-card{break-inside:avoid;box-shadow:none}}';document.head.appendChild(s)}
function coreReportRefinementStyles(){const s=document.createElement('style');s.textContent='.core-narrative{margin-bottom:16px;border-left:5px solid #1f9d7a;background:linear-gradient(135deg,#fff,#edf8f5)}.core-narrative p{font-size:15px;line-height:1.9;margin:8px 0 0;color:#25364a;white-space:pre-line}.core-narrative+ .core-hero{margin-top:0}.core-title .core-actions{flex-shrink:0}';document.head.appendChild(s)}
function removeLegacyReportButton(){document.querySelectorAll('.page-head .report-button,#dashReport .report-button').forEach(x=>x.remove())}
function installKnowledgeNav(){const dataButton=document.querySelector('.dash-nav[data-page=data]');if(!dataButton)return;if(!document.querySelector('.dash-nav[data-page=knowledge]'))dataButton.insertAdjacentHTML('beforebegin','<button class="dash-nav" data-page="knowledge" onclick="dashGo(\'knowledge\')"><i>▧</i><span>知识库</span></button>');if(!document.querySelector('.dash-nav[data-page=lab]'))dataButton.insertAdjacentHTML('beforebegin','<button class="dash-nav" data-page="lab" onclick="dashGo(\'lab\')"><i>⚗</i><span>策略实验室</span></button>')}
async function knowledgeApi(method,path,body){const response=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'}),data=await response.json().catch(()=>({error:'服务器返回格式错误'}));if(!response.ok)throw new Error(data.error||('HTTP '+response.status));return data}
function knowledgeTypes(selected){return['产品合同','会议纪要','产品路演材料','投资观点','产品报告','市场报告','微信文章','其他'].map(x=>`<option ${x===selected?'selected':''}>${x}</option>`).join('')}
async function renderKnowledge(){const host=document.getElementById('dashViewknowledge');if(!host)return;host.innerHTML='<div class=empty-state>正在读取本地知识库…</div>';try{const query=(window.knowledgeQuery||''),data=await knowledgeApi('GET','/api/knowledge?q='+encodeURIComponent(query)),rows=data.documents||[];host.innerHTML=`<div class=dash-heading><div><h2>本地知识库</h2><p>文件与SQLite索引仅保存在本机；当前不连接大模型、不抓取公网内容。</p></div><span class=dash-pill>${rows.length} 份文档</span></div><div class=filter-bar><label>全文检索<input id=knowledgeSearch value="${escapeHtml(query)}" placeholder="标题、正文、产品、机构或标签"></label><button onclick="window.knowledgeQuery=knowledgeSearch.value;renderKnowledge()">搜索</button><label class=link-btn>上传文件<input id=knowledgeUpload type=file hidden accept=".pdf,.docx,.xlsx,.xls,.pptx,.txt,.md,.html,.htm" onchange="uploadKnowledge(this.files[0])"></label><button class=link-btn onclick=importKnowledgeInbox()>导入本机inbox</button></div><div class=dash-card><table><thead><tr><th>标题</th><th>类型</th><th>日期</th><th>产品/机构</th><th>标签</th><th>提取状态</th><th>操作</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${escapeHtml(x.title)}</b><div class=sub>${escapeHtml(x.original_name)}</div></td><td>${escapeHtml(x.document_type)}</td><td>${escapeHtml(x.document_date||'—')}</td><td>${escapeHtml(x.product||x.organization||'—')}</td><td>${escapeHtml((x.tags||[]).join('、'))}</td><td>${escapeHtml(x.extraction_status)}</td><td><button class=link-btn onclick="openKnowledge(${x.id})">查看</button><a class=link-btn href="/api/knowledge/${x.id}/download">下载</a></td></tr>`).join('')||'<tr><td colspan=7>知识库暂无文档，可上传文件或把文件放入 knowledge_base/inbox 后导入。</td></tr>'}</tbody></table></div>`}catch(error){host.innerHTML=`<div class=warn>知识库加载失败：${escapeHtml(error.message)}</div>`}}
async function uploadKnowledge(file){if(!file)return;if(file.size>50*1024*1024){alert('文件不能超过50MB');return}const reader=new FileReader;reader.onload=async()=>{try{const base64=String(reader.result).split(',')[1],type=prompt('文档类型：产品合同、会议纪要、产品路演材料、投资观点、产品报告、市场报告、微信文章或其他','其他')||'其他';await knowledgeApi('POST','/api/knowledge/upload',{filename:file.name,content_base64:base64,metadata:{document_type:type}});renderKnowledge()}catch(error){alert('上传失败：'+error.message)}};reader.readAsDataURL(file)}
async function importKnowledgeInbox(){try{const data=await knowledgeApi('POST','/api/knowledge/import-inbox',{});alert(`导入${data.imported.length}份，重复${data.duplicates.length}份，失败${data.errors.length}份`);renderKnowledge()}catch(error){alert('导入失败：'+error.message)}}
async function openKnowledge(id){try{const x=await knowledgeApi('GET','/api/knowledge/'+id),body=`<style>.knowledge-meta{display:grid;grid-template-columns:1fr 1fr;gap:10px}.knowledge-meta label{display:grid;gap:4px}.knowledge-preview{max-height:50vh;overflow:auto;white-space:pre-wrap;background:#f6f8fb;padding:16px;border-radius:10px}@media(max-width:700px){.knowledge-meta{grid-template-columns:1fr}}</style><div class=knowledge-meta><label>标题<input id=kTitle value="${escapeHtml(x.title)}"></label><label>文档类型<select id=kType>${knowledgeTypes(x.document_type)}</select></label><label>文档日期<input id=kDate value="${escapeHtml(x.document_date||'')}"></label><label>来源<input id=kSource value="${escapeHtml(x.source||'')}"></label><label>相关产品<input id=kProduct value="${escapeHtml(x.product||'')}"></label><label>机构<input id=kOrg value="${escapeHtml(x.organization||'')}"></label><label>作者<input id=kAuthor value="${escapeHtml(x.author||'')}"></label><label>标签（逗号分隔）<input id=kTags value="${escapeHtml((x.tags||[]).join(','))}"></label></div><p><button onclick="opener.saveKnowledge(${x.id},${x.revision},document)">保存元数据</button> <button class=link-btn onclick="opener.deactivateKnowledge(${x.id},${x.revision},document)">移入回收区</button> <a class=link-btn href="/api/knowledge/${x.id}/download">下载原文件</a></p><h3>正文预览</h3><div class=knowledge-preview>${escapeHtml(x.text_content||'未提取到正文；原文件仍已保存。')}</div>`;popup('知识库文档',body)}catch(error){alert(error.message)}}
async function saveKnowledge(id,revision,doc){const get=name=>doc.getElementById(name).value;try{await knowledgeApi('PATCH','/api/knowledge/'+id,{expected_revision:revision,values:{title:get('kTitle'),document_type:get('kType'),document_date:get('kDate'),source:get('kSource'),product:get('kProduct'),organization:get('kOrg'),author:get('kAuthor'),tags:get('kTags')}});doc.defaultView.close();renderKnowledge()}catch(error){alert('保存失败：'+error.message)}}
async function deactivateKnowledge(id,revision,doc){if(!confirm('将该文档移入知识库回收区？'))return;try{await knowledgeApi('DELETE','/api/knowledge/'+id,{expected_revision:revision});doc.defaultView.close();renderKnowledge()}catch(error){alert('操作失败：'+error.message)}}
