function portfolioVarMethodHtml(){return`<div class=dash-card><h3>风控日报全资产简化VaR计算逻辑</h3><p class=dash-note>该模块位于“其他管理”，与FOF底层风控分开。日报金额均为敞口代理，不是实时公允市值；结果不是正式监管VaR或损失预测。</p><table><thead><tr><th>资产或分量</th><th>参数</th><th>计算口径</th></tr></thead><tbody><tr><td>权益FOF</td><td>固定比例5%</td><td>日报产品本金×5%；国泓、长盛汇利2号、长盛海昇5号只计算底层债券，避免与产品本金重复。</td></tr><tr><td>境内固收利率</td><td>中债国债10Y收益率99%右尾VaR（bp）</td><td>人民币敞口×代理久期×利率VaR(bp)÷10000。</td></tr><tr><td>美元固收利率</td><td>美国国债10Y收益率99%右尾VaR（bp）</td><td>所有美元利率资产统一使用10Y；人民币敞口×代理久期×利率VaR(bp)÷10000。</td></tr><tr><td>代理久期</td><td>境内：≤1年0.5、1–3年2、3–5年4、>5年6；Agency MBS 4；其他美元资产3</td><td>剩余期限按（到期日－日报日）÷365.25计算。久期是价格对收益率和利差变化的一阶敏感度。</td></tr><tr><td>信用利差附加风险</td><td>AAA/AAAsf 3bp；AA+/AA 5bp；A+/A 8bp；NR/缺失10bp；次级/劣后/信托12bp；Agency MBS 5bp；其他美元资产10bp</td><td>人民币敞口×代理久期×信用冲击(bp)÷10000；重叠时取较高档。该项是固定管理假设，不是历史统计信用VaR。</td></tr><tr><td>USD/CNY汇率</td><td>人民币升值方向99%历史不利变动率</td><td>美元资产默认未对冲：人民币敞口×汇率VaR率；固定汇率、Quanto或已对冲结构需另行提供标识后剔除或按净敞口计算。</td></tr><tr><td>碳资产</td><td>《碳排放价格.xlsx》统一价格序列99%历史跌幅</td><td>持仓数量×Excel最新价格×碳价VaR率；同一涨跌幅序列统一代理全部碳资产。</td></tr><tr><td>组合汇总</td><td>逐项线性相加</td><td>资产VaR＝利率＋信用＋汇率/碳价等适用分量；组合VaR为300项资产VaR直接求和，不使用相关矩阵。</td></tr></tbody></table><p><b>更新机制：</b><code>python app.py portfolio-var</code>才会主动解析日报、重算缓存并重建网页和Excel；默认<code>refresh</code>、<code>risk</code>和<code>build</code>不重算，只展示上次缓存。</p><p class=warn>一阶线性近似未完整覆盖凸性、提前偿还、负凸性、流动性、违约、融资利率变化及风险因子相关性。</p></div>`}
function researchSection(title,section,renderer){const s=section||{},data=s.data||{},warning=s.error?`<div class=warn>${escapeHtml(s.error)}${s.used_cache?'；展示上次缓存。':''}</div>`:'';return`<details class=dash-card open><summary><b>${title}</b><span class=sub> ${escapeHtml(s.updated_at||'暂无更新')}</span></summary>${warning}${renderer(data)}</details>`}
function basisSnapshot(prefix){const item=(((RAW.risk||{}).futures||{})[prefix])||{},points=item.points||[],latest=points[points.length-1]||{},rows=['当月','下月','当季','下季'].map(t=>{const values=points.map(x=>x[t]&&Number(x[t].value)).filter(Number.isFinite),now=latest[t]&&Number(latest[t].value),change=n=>values.length>n&&Number.isFinite(now)?now-values[values.length-1-n]:null,pctl=values.length&&Number.isFinite(now)?values.filter(x=>x<=now).length/values.length*100:null;return{tenor:t,value:now,d1:change(1),d5:change(5),d21:change(21),percentile:pctl}});return{item,points,rows}}
function drawMarketBasis(){const c=document.getElementById('marketBasisChart'),prefix=document.getElementById('marketBasisPrefix')&&marketBasisPrefix.value,tenor=document.getElementById('marketBasisTenor')&&marketBasisTenor.value,range=document.getElementById('marketBasisRange')&&marketBasisRange.value;if(!c||!prefix)return;let pts=basisSnapshot(prefix).points.map(x=>({date:x.date,value:x[tenor]&&Number(x[tenor].value)})).filter(x=>Number.isFinite(x.value));const days={m1:31,m3:93,y1:366,all:99999}[range]||366;if(range!=='all'&&pts.length){const cutoff=shift(pts[pts.length-1].date,-days);pts=pts.filter(x=>x.date>=cutoff)}const ctx=c.getContext('2d'),L=55,R=20,T=20,B=35,w=c.width-L-R,h=c.height-T-B;ctx.clearRect(0,0,c.width,c.height);if(pts.length<2){ctx.fillText('暂无贴水历史',L,T+20);return}const lo=Math.min(...pts.map(x=>x.value)),hi=Math.max(...pts.map(x=>x.value)),span=hi-lo||1,x=i=>L+i*w/(pts.length-1),y=v=>T+(hi-v)*h/span;ctx.strokeStyle='#16856e';ctx.lineWidth=2;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(x(i),y(p.value)):ctx.moveTo(x(i),y(p.value)));ctx.stroke();ctx.fillStyle='#64748b';ctx.fillText(hi.toFixed(2)+'%',5,T+5);ctx.fillText(lo.toFixed(2)+'%',5,T+h);ctx.fillText(pts[0].date,L,T+h+22);ctx.textAlign='right';ctx.fillText(pts[pts.length-1].date,L+w,T+h+22);ctx.textAlign='left'}
function renderMarketResearch(){const host=document.getElementById('marketResearch');if(!host)return;const r=RAW.market_research||{},basis=['IF','IC','IM'].map(p=>({prefix:p,s:basisSnapshot(p)}));const macro=d=>`<table><thead><tr><th>指标</th><th>数据期</th><th>发布日期</th><th>最新值</th></tr></thead><tbody>${Object.entries(d).map(([k,v])=>{const x=v[v.length-1]||{};return`<tr><td>${k}</td><td>${x.period_end||'—'}</td><td>${x.info_date||'—'}</td><td>${x.value==null?'—':Number(x.value).toFixed(2)}</td></tr>`}).join('')||'<tr><td colspan=4>暂无宏观数据</td></tr>'}</tbody></table>`;const industries=d=>`<table><thead><tr><th>行业/风格</th><th>1月</th><th>3月</th><th>6月</th><th>12月</th><th>20日波动</th><th>相对沪深300</th><th>趋势</th></tr></thead><tbody>${Object.values(d).filter(x=>x.metrics&&x.metrics.status==='ok').sort((a,b)=>(b.metrics.momentum_6m||-99)-(a.metrics.momentum_6m||-99)).map(x=>{const m=x.metrics;return`<tr><td>${x.name}</td><td>${pct((m.momentum_1m||0)*100)}</td><td>${pct((m.momentum_3m||0)*100)}</td><td>${pct((m.momentum_6m||0)*100)}</td><td>${pct((m.momentum_12m||0)*100)}</td><td>${m.volatility_20d==null?'—':pct(m.volatility_20d*100)}</td><td>${m.relative_6m==null?'—':pct(m.relative_6m*100)}</td><td>${m.trend}</td></tr>`}).join('')||'<tr><td colspan=8>暂无行业数据</td></tr>'}</tbody></table>`;const style=d=>`<table><thead><tr><th>风格因子</th><th>最新日</th><th>20日累计</th><th>60日累计</th><th>状态</th></tr></thead><tbody>${Object.entries(d).map(([k,v])=>{const a=v.slice(-20).reduce((s,x)=>s+Number(x.value||0),0),b=v.slice(-60).reduce((s,x)=>s+Number(x.value||0),0),last=v[v.length-1]||{};return`<tr><td>${k}</td><td>${last.date||'—'}</td><td>${pct(a*100)}</td><td>${pct(b*100)}</td><td>${b>0?'占优':'偏弱'}</td></tr>`}).join('')||'<tr><td colspan=5>暂无风格数据</td></tr>'}</tbody></table>`;const arb=d=>`<table><thead><tr><th>商品</th><th>日期</th><th>主力—次主力年化展期收益</th></tr></thead><tbody>${Object.entries(d).map(([k,v])=>{const x=(v.points||[]).slice(-1)[0]||{};return`<tr><td>${v.name} ${k}</td><td>${x.date||'—'}</td><td>${x.value==null?'—':pct(Number(x.value)*100)}</td></tr>`}).join('')||'<tr><td colspan=3>暂无展期数据</td></tr>'}</tbody></table>`;const options=d=>`<table><thead><tr><th>标的</th><th>期限</th><th>日期</th><th>成交量PCR</th><th>持仓PCR</th><th>25Δ Call IV</th><th>25Δ Put IV</th><th>Skew</th></tr></thead><tbody>${Object.values(d).flatMap(x=>Object.entries(x.maturities||{}).map(([m,v])=>{const q=v[v.length-1]||{};return`<tr><td>${x.name}</td><td>${m}</td><td>${q.date||'—'}</td><td>${ratio(q.VL_PCR)}</td><td>${ratio(q.OI_PCR)}</td><td>${q.iv_025_dela==null?'—':pct(Number(q.iv_025_dela)*100)}</td><td>${q.iv_minus_025_dela==null?'—':pct(Number(q.iv_minus_025_dela)*100)}</td><td>${ratio(q.skew)}</td></tr>`})).join('')||'<tr><td colspan=8>暂无期权数据</td></tr>'}</tbody></table>`;const alloc=r.allocation||{},etf=(r.etf_mapping||{}).data||{};host.innerHTML=`<div class=dash-heading><div><h2>市场研究与指数ETF配置看板</h2><p>数据源为Wind缓存与固定白名单RQData；研究信号不构成交易指令。</p></div><span class="dash-pill ${r.errors&&r.errors.length?'attention':'healthy'}">${r.updated_at?'更新 '+r.updated_at:'暂无研究缓存'}</span></div><div class=dash-card><h3>IF / IC / IM 年化贴水</h3><div class=filter-bar><label>品种<select id=marketBasisPrefix>${['IF','IC','IM'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>期限<select id=marketBasisTenor>${['当月','下月','当季','下季'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>区间<select id=marketBasisRange><option value=m1>1月</option><option value=m3>3月</option><option value=y1 selected>1年</option><option value=all>全部</option></select></label></div><canvas id=marketBasisChart width=1100 height=320></canvas><table><thead><tr><th>品种</th><th>期限</th><th>最新</th><th>1日变化</th><th>1周变化</th><th>1月变化</th><th>历史分位</th></tr></thead><tbody>${basis.flatMap(x=>x.s.rows.map(y=>`<tr><td>${x.prefix}</td><td>${y.tenor}</td><td>${y.value==null?'—':y.value.toFixed(2)+'%'}</td><td>${y.d1==null?'—':y.d1.toFixed(2)}</td><td>${y.d5==null?'—':y.d5.toFixed(2)}</td><td>${y.d21==null?'—':y.d21.toFixed(2)}</td><td>${y.percentile==null?'—':y.percentile.toFixed(1)+'%'}</td></tr>`)).join('')}</tbody></table></div>${researchSection('宏观状态',r.macro,macro)}${researchSection('申万一级行业与风格指数轮动',r.industry_indices,industries)}${researchSection('米筐风格因子',r.style_factor_returns,style)}${researchSection('套利策略监控',r.arbitrage,arb)}${researchSection('情绪与场内期权结构',r.option_surfaces,options)}<div class=dash-card><h3>月度指数ETF建议权重</h3><p class=sub>${escapeHtml(alloc.method||'研究缓存不足，暂不输出建议。')}；基准：沪深300；默认单边成本10bp，敏感性0/10/20bp。</p><table><thead><tr><th>指数</th><th>映射ETF</th><th>综合评分</th><th>60日波动</th><th>建议权重</th><th>信号贡献</th></tr></thead><tbody>${(alloc.recommendations||[]).map(x=>`<tr><td>${x.code}</td><td>${escapeHtml((etf[x.code]||{}).selected||'暂无合格ETF')}</td><td>${Number(x.score).toFixed(3)}</td><td>${pct(Number(x.volatility_60d)*100)}</td><td><b>${pct(Number(x.weight)*100)}</b></td><td>${Object.entries(x.components||{}).map(y=>y[0]+' '+Number(y[1]).toFixed(2)).join('；')}</td></tr>`).join('')||'<tr><td colspan=6>暂无可用建议权重</td></tr>'}</tbody></table><div class=warn>当前回测状态：${escapeHtml((alloc.backtest||{}).status||'未生成')}。配置建议无杠杆、无做空、月度调仓，不连接交易系统。</div></div>`;['marketBasisPrefix','marketBasisTenor','marketBasisRange'].forEach(id=>document.getElementById(id).onchange=drawMarketBasis);drawMarketBasis()}
function renderDashData(){const host=document.getElementById('dashData'),h=dashHealthData(),labelMatches=Object.entries(((RAW.labels||{}).matches)||{}).filter(x=>x[1].match_status!=='已匹配').map(x=>Object.assign({query_name:x[0]},x[1])),strategyIndexIssues=strategyNameIndexIssues(),dedupe=(RAW.labels||{}).dedupe_check||{},duplicateIssues=(dedupe.duplicates||[]).map(x=>Object.assign({},x,{reason:(x.conflicts||[]).length?'同名记录存在人工字段冲突，运行时保留信息更完整的记录；冲突字段：'+x.conflicts.map(y=>y.field).join('、'):'同名记录的非冲突字段已合并为一个运行时标签'})),marketIssues=Object.values(((RAW.benchmarks||{}).indices)||{}).filter(x=>x.error),underlyingIssues=((RAW.underlying_assets||{}).errors||[]);host.innerHTML=`<div class=dash-heading><div><h2>数据与说明</h2><p>“需关注”是以下数据完整性提示的合计，不等同于收益计算错误。点击分类可查看每一项。</p></div>${dashStatus()}</div><div class=source-grid>${[['FOF估值表','资产、净值、底层持仓',h.parse],['资金台账','申购、赎回、分红、当前本金',h.ledger],['Wind数据库','指数、期货、风险价值与贴水',h.market],['标签文件','策略、管理人、专户/集合、营业部',strategyIndexIssues.length+duplicateIssues.length],['底层估值表','证券持仓与多空敞口',underlyingIssues.length]].map(x=>`<div class=dash-card><h3>${x[0]}</h3><p>${x[1]}</p><span class="dash-pill ${x[2]?'attention':'healthy'}">${x[2]?'需检查 '+x[2]+' 项':'正常'}</span></div>`).join('')}</div><div class=dash-card issue-list><h3>数据提示明细</h3>${dashIssueSection('估值表解析提示',RAW.parse_errors||[],'估值文件无法解析或字段不完整的记录。')}${dashIssueSection('资金台账提示',RAW.ledger_errors||[],'台账日期、金额或产品勾稽产生的提示。')}${dashIssueSection('策略组合产品名称索引提示',strategyIndexIssues,'期末底层持仓的产品名称会自动补录到产品标签，默认管理人为空、标签/形式为“其他”、营业部为“无”；本节只保留仍无法匹配的异常。')}${dashIssueSection('产品标签名称除重检查',duplicateIssues,`按标准化产品名称检查 ${dedupe.checked_records||0} 条启用记录，得到 ${dedupe.unique_product_names||0} 个唯一名称；运行时只使用每个名称的一条有效标签，原始记录及ID继续保留以供审计。`)}${dashIssueSection('产品标签归入其他',labelMatches,'未匹配或存在歧义的底层产品默认归入“其他”参与统计；自动补录记录也保持“其他”，等待在产品标签页人工完善。')}${dashIssueSection('指数行情提示',marketIssues,'指数缓存更新或行情字段异常的记录。')}${dashIssueSection('底层估值表提示',underlyingIssues,'底层证券持仓及敞口解析提示。')}</div>${portfolioVarMethodHtml()}<div class=dash-card><h3>项目资料</h3><div class=doc-buttons>${['计算口径','资金台账','代码指令','历史改动'].map(x=>`<button onclick="openInfo('${x}')">${x}</button>`).join('')}</div></div>`}
const HOME_GROUPS=[{id:'returns',icon:'↗',title:'计算收益',note:'查看组合、FOF与底层收益',items:[['总览','overview',''],['FOF层','returns',''],['底层','bottom-returns',''],['策略层','strategy','']]},{id:'data',icon:'▦',title:'数据管理',note:'维护标签、台账与估值表',items:[['标签','labels',''],['台账','data','ledger'],['估值表','overview','report']]},{id:'systems',icon:'⌘',title:'其他系统',note:'进入风控、知识与研究工具',items:[['风控系统','risk',''],['知识库','knowledge',''],['策略实验室','lab','']]}];
function renderHome(){const host=document.getElementById('dashViewhome');if(!host)return;host.innerHTML=`<div class=home-shell><div class=home-hero><span class=home-eyebrow>FOF MANAGEMENT SYSTEM</span><h2>欢迎来到FOF管理系统，想查阅什么功能？</h2><p>选择一个功能分类，快速进入对应的管理与分析页面。</p></div><div class=home-groups>${HOME_GROUPS.map(group=>`<section class=home-group data-home-group="${group.id}"><button class=home-group-trigger aria-expanded=false aria-controls="homeActions-${group.id}" onclick="toggleHomeGroup('${group.id}')"><span class=home-group-icon>${group.icon}</span><span><b>${group.title}</b><small>${group.note}</small></span><i aria-hidden=true>＋</i></button><div class=home-actions id="homeActions-${group.id}" aria-hidden=true>${group.items.map((item,index)=>`<button style="--home-order:${index}" tabindex=-1 onclick="dashShortcut('${item[1]}','${item[2]}')"><span>${item[0]}</span><i aria-hidden=true>→</i></button>`).join('')}</div></section>`).join('')}</div></div>`}
function toggleHomeGroup(id){document.querySelectorAll('[data-home-group]').forEach(group=>{const active=group.dataset.homeGroup===id&&!group.classList.contains('active'),trigger=group.querySelector('.home-group-trigger'),actions=group.querySelector('.home-actions');group.classList.toggle('active',active);trigger.setAttribute('aria-expanded',String(active));actions.setAttribute('aria-hidden',String(!active));actions.querySelectorAll('button').forEach(button=>button.tabIndex=active?0:-1)})}
function dashShortcut(page,target){dashGo(page,false,target||'')}
function renderInlineLedger(){const host=document.getElementById('dashData');if(!host)return;const tables=RAW.ledger_tables||{},names=Object.keys(tables),old=document.getElementById('dataLedgerPanel');if(old)old.remove();host.insertAdjacentHTML('beforeend',`<section id=dataLedgerPanel class="dash-card ledger-inline"><div class=card-head><div><h3>资金台账</h3><p class=dash-note>只读展示本地资金台账，可切换工作表并搜索当前表。</p></div><span class=dash-pill>${names.length} 个工作表</span></div>${names.length?`<div class=filter-bar><label>工作表<select id=inlineLedgerSheet>${names.map((name,index)=>`<option value="${index}">${escapeHtml(name)}</option>`).join('')}</select></label><label>搜索<input id=inlineLedgerSearch placeholder="搜索当前工作表"></label></div><div id=inlineLedgerGrid class=ledger-grid></div>`:'<div class=warn>资金台账模块尚未加载或暂无可用工作表。</div>'}</section>`);if(!names.length)return;const render=()=>{const rows=tables[names[Number(document.getElementById('inlineLedgerSheet').value)]]||[],query=document.getElementById('inlineLedgerSearch').value.toLowerCase();document.getElementById('inlineLedgerGrid').innerHTML=dataTable(rows,query)};document.getElementById('inlineLedgerSheet').onchange=render;document.getElementById('inlineLedgerSearch').oninput=render;render()}
const renderDashDataBase=renderDashData;renderDashData=function(){renderDashDataBase();renderInlineLedger()};
function focusDashTarget(page,target){document.querySelectorAll('.dash-target-flash').forEach(x=>x.classList.remove('dash-target-flash'));let element=null,focus=null;if(page==='data'&&target==='ledger'){element=document.getElementById('dataLedgerPanel');focus=document.getElementById('inlineLedgerSearch')}if(page==='overview'&&target==='report'){focus=document.getElementById('valuationArchiveDate');element=focus&&focus.closest('.comparison-controls')}if(!element)return;element.classList.add('dash-target-flash');element.scrollIntoView({behavior:'smooth',block:'center'});if(focus)setTimeout(()=>focus.focus({preventScroll:true}),260)}
function installHomeNavigation(){const brand=document.querySelector('.dash-brand');if(brand){const button=document.createElement('button');button.className='dash-brand dash-home-button';button.type='button';button.setAttribute('aria-label','返回FOF管理系统首页');button.innerHTML=brand.innerHTML;button.onclick=()=>dashGo('home');brand.replaceWith(button)}const top=document.querySelector('.dash-top');if(top&&!top.querySelector('.dash-mobile-home')){const button=document.createElement('button');button.className='dash-mobile-home';button.type='button';button.setAttribute('aria-label','返回FOF管理系统首页');button.textContent='FOF';button.onclick=()=>dashGo('home');top.insertBefore(button,top.firstChild)}}
function openOtherManagement(){const body=`<style>.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{background:#f2f5f9;border-radius:9px;padding:12px}.value{font-size:20px;font-weight:700}.warn{background:#fff2d9;border-left:3px solid #c6923c;padding:10px;margin:10px 0}details{border:1px solid #d9ddd5;border-radius:8px;padding:10px;margin:10px 0}summary{cursor:pointer}</style><p class=sub>该模块独立于FOF底层风控。默认每日刷新、市场风险更新和网页构建只展示上次缓存；执行 <code>python app.py portfolio-var</code> 才会重新解析风控日报并计算。</p>${portfolioVarHtml()}`;popup('其他管理',body)}
function dashEmbed(page){const suffix=page==='risk'?'Risk':page==='underlying'?'Underlying':'Other';dashState.embed=document.getElementById('dash'+suffix);try{page==='risk'?openRisk():page==='underlying'?openUnderlyingAssets():openOtherManagement()}finally{dashState.embed=null}}
