const bottomReturnState={active:null,query:'',benchmark:'000852',page:0,pageSize:100,data:null,loading:false};
function documentTopLevelExclusionChange(){const cards=document.querySelectorAll('.info-card'),method=cards[0]&&cards[0].querySelector('.info-body'),history=cards[2]&&cards[2].querySelector('.info-body');if(method)method.insertAdjacentHTML('beforeend','<p><b>底层产品范围：</b>“组合多空”和“底层收益”均按标准化产品名称精确排除配置中的17只顶层FOF，不按名称是否包含“FOF”粗略判断。底层收益当前登记18个真正底层产品，必须通过顶层FOF估值表中的实际历史持仓名称建立关联；产品与父FOF自身同名不构成关联。</p>');if(history)history.insertAdjacentHTML('afterbegin','<div class="history-item"><b>2026-09-11 · 本次更新</b><br>组合多空和底层收益统一排除17只配置顶层FOF；移除底层收益的父FOF同名自关联，登记清单由19个修正为18个真正底层产品。</div>')}
function bottomReturnStyles(){if(document.getElementById('bottomReturnStyles'))return;const style=document.createElement('style');style.id='bottomReturnStyles';style.textContent='.bottom-layout{display:grid;grid-template-columns:330px minmax(0,1fr);gap:16px}.bottom-side{align-self:start;position:sticky;top:92px}.bottom-side input{width:100%}.bottom-list{display:flex;flex-direction:column;gap:8px;margin-top:12px;max-height:70vh;overflow:auto}.bottom-product{display:flex;flex-direction:column;align-items:flex-start;text-align:left;background:#f8fafc;color:#334155;border:1px solid #dfe5ed;padding:12px}.bottom-product.active{background:#e8f5f1;border-color:#0f7d63;box-shadow:0 0 0 1px #0f7d63}.bottom-product small,.bottom-product em{font-size:11px;color:#718096;font-style:normal}.bottom-detail{min-width:0}.bottom-metrics{grid-template-columns:repeat(5,minmax(130px,1fr))}.bottom-metrics strong{display:block;font-size:18px;margin-top:4px}.bottom-metrics small{display:block;color:#718096}.bottom-section{margin-top:18px;padding-top:14px;border-top:1px solid #dfe5ed;overflow:auto}.bottom-section canvas{max-width:100%;height:auto}.bottom-pager{display:flex;justify-content:flex-end;gap:8px;margin-top:10px}.bottom-pager button:disabled{opacity:.4;cursor:not-allowed}@media(max-width:1000px){.bottom-layout{grid-template-columns:1fr}.bottom-side{position:static}.bottom-metrics{grid-template-columns:repeat(2,1fr)}}';document.head.appendChild(style)}
function bottomProductAllowed(product){return (product.fof_products||[]).some(name=>dashAllowed(name))}
