function renderBottomReturns(){const host=document.getElementById('dashBottomReturns');if(!host)return;bottomReturnStyles();const products=bottomVisibleProducts();if(bottomReturnState.active&&!products.some(x=>x.product_id===bottomReturnState.active)){bottomReturnState.active=null;bottomReturnState.data=null}if(!bottomReturnState.active&&products.length)bottomReturnState.active=products[0].product_id;host.innerHTML=`<div class=dash-heading><div><h2>底层收益</h2><p>对本地登记且具有再穿透估值表的底层产品进行保守净值与持仓收益分析。</p></div><span class=dash-pill>${(RAW.bottom_returns||{}).product_count||0} 个登记产品</span></div><div class=bottom-layout><aside class="dash-card bottom-side"><input id=bottomSearch placeholder="搜索底层产品名称" value="${escapeHtml(bottomReturnState.query)}"><div class=bottom-list>${products.length?products.map(x=>`<button class="bottom-product ${x.product_id===bottomReturnState.active?'active':''}" data-id="${x.product_id}"><b>${escapeHtml(x.product)}</b><small>${escapeHtml((x.fof_products||[]).join('、'))}</small><em>${x.start_date||'—'} → ${x.end_date||'—'} · ${x.status}</em></button>`).join(''):'<div class=warn>当前分析范围或搜索条件下没有已登记的底层产品。</div>'}</div></aside><div id=bottomReturnDetail class="dash-card bottom-detail"></div></div>`;document.getElementById('bottomSearch').oninput=e=>{bottomReturnState.query=e.target.value;renderBottomReturns()};host.querySelectorAll('.bottom-product').forEach(button=>button.onclick=()=>{bottomReturnState.active=button.dataset.id;bottomReturnState.page=0;bottomReturnState.data=null;renderBottomReturns()});if(bottomReturnState.data&&bottomReturnState.data.product&&bottomReturnState.data.product.product_id===bottomReturnState.active)renderBottomReturnDetail();else if(bottomReturnState.active)loadBottomReturn(bottomReturnState.active)}
