function renderBottomHoldings(){const d=bottomReturnState.data,host=document.getElementById('bottomHoldingTable');if(!d||!host)return;const rows=d.holdings||[],pages=Math.max(1,Math.ceil(rows.length/bottomReturnState.pageSize));bottomReturnState.page=Math.min(bottomReturnState.page,pages-1);const start=bottomReturnState.page*bottomReturnState.pageSize,slice=rows.slice(start,start+bottomReturnState.pageSize);host.innerHTML=coreTable(['资产类型','代码 / 名称','期初数量 / 价格','期末数量 / 价格','期末市值','日 / 周 / 区间价格变化','可归属估算收益','归属状态'],slice.map(x=>`<tr><td>${escapeHtml(x.asset_type)}</td><td>${escapeHtml(x.code)}<div class=sub>${escapeHtml(x.name)}</div></td><td>${x.start_quantity==null?'—':x.start_quantity}<div class=sub>${x.start_price==null?'—':x.start_price}</div></td><td>${x.end_quantity==null?'—':x.end_quantity}<div class=sub>${x.end_price==null?'—':x.end_price}</div></td><td>${money(x.end_market_value)}</td><td>${pct(x.daily_change)} / ${pct(x.weekly_change)} / ${pct(x.period_change)}</td><td class=${cls(x.estimated_profit)}>${money(x.estimated_profit)}<div class=sub>${x.contribution==null?'—':pct(x.contribution)}</div></td><td>${escapeHtml(x.status)}</td></tr>`));document.getElementById('bottomPageInfo').textContent=`第 ${bottomReturnState.page+1} / ${pages} 页，每页最多 ${bottomReturnState.pageSize} 项`;const prev=document.getElementById('bottomPrev'),next=document.getElementById('bottomNext');prev.disabled=bottomReturnState.page<=0;next.disabled=bottomReturnState.page>=pages-1;prev.onclick=()=>{bottomReturnState.page--;renderBottomHoldings()};next.onclick=()=>{bottomReturnState.page++;renderBottomHoldings()}}
function drawBottomLine(){const d=bottomReturnState.data,c=document.getElementById('bottomComparison');if(!d||!c)return;const p=(d.points||[]).filter(x=>x.accumulated_nav),m=(d.benchmark_points||[]).filter(x=>x.close);if(!p.length)return;const p0=p[0].accumulated_nav,m0=m.length?m[0].close:null,series=[{name:d.product.product,color:'#0f7d63',points:p.map(x=>({date:x.valuation_date,value:x.accumulated_nav/p0*100}))},{name:BOTTOM_BENCHMARKS[d.benchmark_code],color:'#b47a2e',points:m0?m.map(x=>({date:x.date,value:x.close/m0*100})):[]}],all=series.flatMap(x=>x.points),ctx=c.getContext('2d'),L=54,R=20,T=28,B=42,w=c.width-L-R,h=c.height-T-B,min=Math.min(...all.map(x=>x.value)),max=Math.max(...all.map(x=>x.value)),span=max-min||1,start=new Date(d.actual_start).getTime(),end=new Date(d.actual_end).getTime(),x=v=>L+(new Date(v).getTime()-start)/(end-start||1)*w,y=v=>T+(max-v)/span*h;ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle='#e2e8f0';for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(L,T+h*i/4);ctx.lineTo(L+w,T+h*i/4);ctx.stroke()}series.forEach((s,j)=>{ctx.strokeStyle=s.color;ctx.lineWidth=2.5;ctx.beginPath();s.points.forEach((q,i)=>(i?ctx.lineTo(x(q.date),y(q.value)):ctx.moveTo(x(q.date),y(q.value))));ctx.stroke();ctx.fillStyle=s.color;ctx.fillRect(L+j*190,T-20,14,4);ctx.fillStyle='#475569';ctx.font='12px Microsoft YaHei';ctx.fillText(s.name,L+20+j*190,T-14)});ctx.fillStyle='#64748b';ctx.fillText(d.actual_start,L,c.height-12);ctx.fillText(d.actual_end,L+w-72,c.height-12)}
function bottomContributionRows(holdings){const compare=(a,b)=>Number(b.estimated_profit)-Number(a.estimated_profit)||String(a.name||'').localeCompare(String(b.name||''),'zh-CN'),ranked=(holdings||[]).filter(x=>x&&x.estimated_profit!=null&&Number.isFinite(Number(x.estimated_profit))).slice().sort(compare);if(ranked.length<=20)return{rows:ranked,omitted:0,split:0};const rows=[...new Set(ranked.slice(0,10).concat(ranked.slice(-10)))].sort(compare);return{rows,omitted:ranked.length-rows.length,split:10}}
function drawBottomContribution(){const d=bottomReturnState.data,c=document.getElementById('bottomContribution');if(!d||!c)return;const selection=bottomContributionRows(d.holdings),data=selection.rows,note=document.getElementById('bottomContributionNote'),gap=selection.omitted?34:0,T=20,B=20,rowHeight=26;note.textContent=selection.omitted?`按可归属估算收益金额从高到低展示贡献最高10项和最低10项，已省略中间${selection.omitted}项；仓位变化金额不计作收益，退出持仓无成交价时标记未归属。`:`按可归属估算收益金额从高到低展示全部${data.length}项；仓位变化金额不计作收益，退出持仓无成交价时标记未归属。`;c.height=Math.max(320,T+B+data.length*rowHeight+gap);const ctx=c.getContext('2d'),L=210,R=75,w=c.width-L-R,h=c.height-T-B-gap,max=Math.max(1,...data.map(x=>Math.abs(Number(x.estimated_profit)))),slot=h/Math.max(data.length,1);ctx.clearRect(0,0,c.width,c.height);data.forEach((q,i)=>{const offset=selection.omitted&&i>=selection.split?gap:0,y=T+i*slot+offset+4,value=Number(q.estimated_profit),bw=Math.abs(value)/max*w/2,x=value>=0?L+w/2:L+w/2-bw;ctx.fillStyle=value>=0?'#e95845':'#0a9b77';ctx.fillRect(x,y,bw,Math.max(5,slot-8));ctx.fillStyle='#475569';ctx.font='11px Microsoft YaHei';ctx.textAlign='right';ctx.fillText(String(q.name||'').slice(0,20),L-8,y+slot/2+3);ctx.textAlign=value>=0?'left':'right';ctx.fillText(new Intl.NumberFormat('zh-CN',{maximumFractionDigits:0}).format(value),value>=0?x+bw+5:x-5,y+slot/2+3)});if(selection.omitted){const separatorY=T+selection.split*slot+gap/2;ctx.save();ctx.setLineDash([5,5]);ctx.strokeStyle='#cbd5e1';ctx.beginPath();ctx.moveTo(L,separatorY);ctx.lineTo(L+w,separatorY);ctx.stroke();ctx.restore();ctx.fillStyle='#718096';ctx.font='11px Microsoft YaHei';ctx.textAlign='center';ctx.fillText(`已省略中间${selection.omitted}项`,L+w/2,separatorY-5)}ctx.strokeStyle='#94a3b8';ctx.beginPath();ctx.moveTo(L+w/2,T);ctx.lineTo(L+w/2,T+h+gap);ctx.stroke()}
