function documentHomeChange(){const cards=document.querySelectorAll('.info-card'),method=cards[0]&&cards[0].querySelector('.info-body'),history=cards[2]&&cards[2].querySelector('.info-body');if(method)method.insertAdjacentHTML('beforeend','<p><b>欢迎首页与快捷入口：</b>网页根地址和空Hash默认进入欢迎首页，<code>run</code>自动打开地址及分享地址文件显式使用 <code>#home</code>；点击左上角“投资资产组合”可随时返回。首页按计算收益、数据管理和其他系统展开功能入口；资金台账使用 <code>#data/ledger</code> 在数据与说明内只读展示，估值表使用 <code>#overview/report</code> 定位投资总览的报告出具。原有页面Hash继续兼容。</p>');if(history)history.insertAdjacentHTML('afterbegin','<div class="history-item"><b>2026-09-11 · 本次更新</b><br>新增动态欢迎首页和功能快捷入口；本地自动打开及分享地址显式指向 <code>#home</code>，左上角品牌可返回首页；资金台账与报告出具支持可刷新恢复的精准深链接，并补充键盘、移动端和减少动态效果支持。</div>')}
function documentDashboardChange(){const cards=document.querySelectorAll('.info-card'),method=cards[0]&&cards[0].querySelector('.info-body'),history=cards[2]&&cards[2].querySelector('.info-body');if(method)method.insertAdjacentHTML('beforeend','<p><b>投资驾驶舱：</b>全局日期和分析范围由顶部筛选栏统一控制；左侧导航按投资总览、收益、市场、策略、风险、底层及数据说明分层。持仓明细统一保留在顶层收益中，不再设置重复的独立持仓页面。页面地址使用Hash保存当前模块和产品位置，刷新后可恢复。“需关注”统计估值解析、资金台账、产品标签和指数行情的数据完整性提示，可点击进入“数据与说明”逐项核查，不代表同等数量的收益错误或投资风险。</p><p><b>Barra与交易归因：</b>在证券级因子数据和底层真实交易流水接入前仅显示数据需求，不计算或展示模拟结果。</p>');if(history)history.insertAdjacentHTML('afterbegin','<div class="history-item"><b>2026-09-08 · 本次更新</b><br>策略实验室接入LLM双通道（云端API+本地ollama兜底）：界面选择方法论与目标后由大模型生成受schema校验的策略规格，本地解释执行并强制全部组合约束；新增任务提交与轮询接口，凭据只从.env读取。</div><div class="history-item"><b>2026-08-27 · 本次更新</b><br>删除与顶层收益重复的“持仓与穿透”独立页面；旧地址自动转入顶层收益，底层持仓矩阵和内联曲线继续保留。</div><div class="history-item"><b>2026-08-17 · 本次更新</b><br>完善驾驶舱数据提示：顶部及首页异常数字可直接进入明细，数据与说明页面按估值解析、资金台账、产品标签、指数行情和底层估值表逐项折叠展示；移除装饰性英文副标题和左侧底部说明。</div><div class="history-item"><b>2026-08-17 · 本次更新</b><br>网页重构为FOF投资驾驶舱：新增深色左侧导航、顶部全局筛选、管理层总览、异常待办、Hash路由及统一的风险和底层分析视图；Barra和交易归因保留禁用入口并披露所需数据。</div>')}
let factorSelectedDate=null;const renderMultiFactorBase=renderMultiFactor;renderMultiFactor=function(selected){const data=RAW.factors||{},snapshots=data.snapshots||[];if(snapshots.length){if(!factorSelectedDate)factorSelectedDate=snapshots[snapshots.length-1].valuation_date;const snap=snapshots.find(x=>x.valuation_date===factorSelectedDate)||snapshots[snapshots.length-1],oldProducts=data.products,oldDate=data.factor_date;data.products=snap.products;data.factor_date=snap.factor_date;renderMultiFactorBase(selected);data.products=oldProducts;data.factor_date=oldDate;const bar=document.querySelector('#dashBarra .filter-bar');if(bar){const label=document.createElement('label');label.innerHTML=`多因子估值日期<select id=factorValuationDate>${snapshots.map(x=>`<option value="${x.valuation_date}" ${x.valuation_date===snap.valuation_date?'selected':''}>${x.valuation_date}</option>`).join('')}</select>`;bar.insertBefore(label,bar.firstChild);factorValuationDate.onchange=()=>{factorSelectedDate=factorValuationDate.value;renderMultiFactor(0)}}return}renderMultiFactorBase(selected)}
function documentFactorChange(){const cards=document.querySelectorAll('.info-card'),method=cards[0]&&cards[0].querySelector('.info-body'),history=cards[2]&&cards[2].querySelector('.info-body');if(method){method.querySelectorAll('p').forEach(x=>{if(x.textContent.includes('Barra与交易归因'))x.remove()});method.insertAdjacentHTML('beforeend','<p><b>多因子分析：</b>多因子估值日期仅列出已缓存快照；选择后使用该快照的实际持仓估值日，并匹配不晚于估值日的最近Wind因子日，绝不使用未来因子。历史底层估值表只读解析证券级股票叶子科目。规模、价值、动量、波动、流动性、成长、盈利、杠杆和股息因子在同日A股截面按1%/99%缩尾后标准化，再按证券市值加权形成产品暴露；行业来自Wind有效期行业映射并兼容Wind行业代码补零规则。该模块是自研暴露分析，不是MSCI Barra正式风险模型，不计算因子协方差风险、特异风险、跟踪误差或正式风险贡献。</p>')}if(history)history.insertAdjacentHTML('afterbegin','<div class="history-item"><b>2026-08-18 · 本次更新</b><br>多因子分析新增估值日期选择，按快照分别展示实际估值日、因子日和证券暴露；修正Wind行业分类10位代码与16位补零字典无法连接的问题。</div><div class="history-item"><b>2026-08-18 · 本次更新</b><br>安全解压并按内容哈希整理历史底层估值表；新增证券级Wind九类风格因子、行业配置、覆盖率、持仓明细和产品筛选，将原Barra占位入口改为多因子分析并明确模型边界。</div>');const style=document.createElement('style');style.textContent='.dash-nav[data-page="barra"] em{display:none}';document.head.appendChild(style)}
renderLabelEditorPage=async function(){
 const host=document.getElementById('dashLabels');if(!host)return;
 host.innerHTML=`<div class="dash-heading"><div><h2>产品标签</h2><p>底层产品的策略、管理人、专户/集合及营业部标签在线编辑器；营业部默认“无”，只接受人工在线填写。</p></div><span class="dash-pill" id=labelPagePill>读取中…</span></div><div class="filter-bar"><label>搜索<input id=labelSearch placeholder="产品、管理人、营业部或标签"></label><label>状态<select id=labelStatus><option value=active>启用</option><option value=all>全部</option><option value=inactive>已停用</option></select></label><button id=labelNew>新增标签</button><button id=labelReload>刷新</button></div><div class="dash-card"><div id=labelMsg class=dash-note style="padding:8px 10px;background:#f3f6f8;border-radius:7px;margin:0 0 10px"></div><div id=labelGrid style="overflow:auto"></div></div>`;
 let catalog=null;const fields=['product','manager','primary','secondary','vehicle','department','classification_basis'],headers=['产品名称','管理人','一级标签','二级标签','形式','营业部','分类依据','状态','操作'];
 const load=async()=>{try{catalog=await labelApi('GET','/api/labels');refreshLabelDependentViews(catalog);render()}catch(e){document.getElementById('labelMsg').textContent='读取失败：'+e.message}};
 const render=()=>{const q=document.getElementById('labelSearch').value.trim().toLowerCase(),status=document.getElementById('labelStatus').value,source=status==='active'?(catalog.deduped_records||catalog.records||[]):(catalog.records||[]),all=source.filter(x=>(status==='all'||(status==='active'&&x.active!==false)||(status==='inactive'&&x.active===false))&&(!q||fields.some(f=>String(x[f]||'').toLowerCase().includes(q)))),rows=all.slice(0,300),duplicateGroups=((catalog.dedupe_check||{}).duplicate_groups||0);document.getElementById('labelPagePill').textContent=`修订号 ${catalog.revision} · ${all.length} 条`;document.getElementById('labelMsg').textContent=`匹配 ${all.length} 条；启用列表已按产品名称除重${duplicateGroups?'，发现 '+duplicateGroups+' 组原始同名记录，详情见“数据与说明”':''}${all.length>300?'；当前显示前300条，请继续搜索缩小范围':''}`;document.getElementById('labelGrid').innerHTML=`<table class=lab-table style="min-width:1180px"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr data-id="${x.record_id}">${fields.map(f=>`<td><input data-field="${f}" value="${escapeHtml(x[f]||(f==='department'?'无':''))}" style="width:100%;min-width:${f==='product'?'190':'90'}px;padding:5px 8px;border:1px solid var(--line);border-radius:6px"></td>`).join('')}<td>${x.active===false?'已停用':'启用'}<div class=sub>v${x.version||1}</div></td><td><button data-action=save style="padding:5px 10px">保存</button>${x.active===false?'':`<button data-action=disable style="padding:5px 10px;background:#a13e35">停用</button>`}</td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('#labelGrid [data-action]').forEach(button=>button.onclick=async()=>{const row=button.closest('tr'),id=row.dataset.id;try{if(button.dataset.action==='disable')await labelApi('DELETE','/api/labels/'+encodeURIComponent(id),{expected_revision:catalog.revision});else{const values={};row.querySelectorAll('[data-field]').forEach(input=>values[input.dataset.field]=input.value);await labelApi('PATCH','/api/labels/'+encodeURIComponent(id),{expected_revision:catalog.revision,values})}await load()}catch(e){document.getElementById('labelMsg').textContent='保存失败：'+e.message}})};
 document.getElementById('labelSearch').oninput=render;document.getElementById('labelStatus').onchange=render;document.getElementById('labelReload').onclick=load;document.getElementById('labelNew').onclick=async()=>{const product=prompt('产品名称');if(!product)return;try{await labelApi('POST','/api/labels',{expected_revision:catalog.revision,values:{product,manager:'',primary:'其他',secondary:'其他',vehicle:'其他',department:'无',classification_basis:'网页新增'}});await load()}catch(e){document.getElementById('labelMsg').textContent='新增失败：'+e.message}};await load()
};
