function drawHoldingLine(c,points,field,color,tipId){const ctx=c.getContext('2d'),L=72,R=20,T=20,B=45,valid=points.filter(x=>Number.isFinite(Number(x[field]))),w=c.width-L-R,h=c.height-T-B;ctx.clearRect(0,0,c.width,c.height);if(!valid.length){ctx.fillStyle='#718096';ctx.fillText('暂无可用数据',L,T+20);return}const values=valid.map(x=>Number(x[field])),min=Math.min(...values),max=Math.max(...values),span=max-min||Math.max(Math.abs(max)*.01,1),xp=i=>L+i*w/Math.max(valid.length-1,1),yp=v=>T+(max-v)/span*h;ctx.font='12px Microsoft YaHei';for(let i=0;i<=4;i++){const yy=T+h*i/4,v=max-span*i/4;ctx.strokeStyle='#e1e7ee';ctx.beginPath();ctx.moveTo(L,yy);ctx.lineTo(L+w,yy);ctx.stroke();ctx.fillStyle='#718096';ctx.fillText(field==='market_value'?(v/10000).toFixed(1)+'万':v.toFixed(4),5,yy+4)}ctx.strokeStyle=color;ctx.lineWidth=2.5;ctx.beginPath();valid.forEach((p,i)=>i?ctx.lineTo(xp(i),yp(Number(p[field]))):ctx.moveTo(xp(i),yp(Number(p[field]))));ctx.stroke();ctx.fillStyle='#718096';ctx.fillText(valid[0].valuation_date,L,c.height-15);ctx.fillText(valid[valid.length-1].valuation_date,c.width-92,c.height-15);let tip=c.ownerDocument.getElementById(tipId);if(!tip){tip=c.ownerDocument.createElement('div');tip.id=tipId;tip.className='chart-tip';c.ownerDocument.body.appendChild(tip)}c.onmousemove=e=>{const rect=c.getBoundingClientRect(),cx=(e.clientX-rect.left)*c.width/rect.width,i=Math.max(0,Math.min(valid.length-1,Math.round((cx-L)/Math.max(w,1)*(valid.length-1)))),p=valid[i],value=field==='market_value'?money(p[field]):Number(p[field]).toFixed(4);tip.innerHTML=`<b>${p.valuation_date}</b><br>${field==='market_value'?'持仓市值':'估值价格代理'}：${value}`;tip.style.display='block';tip.style.left=Math.min(e.clientX+14,c.ownerDocument.defaultView.innerWidth-tip.offsetWidth-8)+'px';tip.style.top=Math.min(e.clientY+14,c.ownerDocument.defaultView.innerHeight-tip.offsetHeight-8)+'px'};c.onmouseleave=()=>tip.style.display='none'}
