function renderProductReturnTable(reset){const host=document.getElementById('dashOverview');if(!host||!report.length)return;const items=RAW.products.map((raw,index)=>({raw,index,calculated:report[index]})).filter(x=>dashAllowed(x.raw.name)),context=startDate.value+'|'+endDate.value+'|'+dashState.scope;if(!productReturnSelection||reset&&productReturnContext!==context)productReturnSelection=new Set(items.map(x=>x.raw.name));productReturnContext=context;let section=document.getElementById('productReturnTable');if(!section){host.insertAdjacentHTML('afterbegin','<section id=productReturnTable class="dash-card product-return-card"></section>');section=document.getElementById('productReturnTable')}const total=productReturnAggregate(items),dash='—',cell=(value,kind)=>value==null?dash:kind==='pct'?pct(value):money(value);section.innerHTML=`<div class=card-head><div><h3>FOF产品收益计算</h3><p class=dash-note>默认勾选当前分析范围内全部顶层FOF；勾选仅影响本表合计，不改变投资总览、报告或其他页面。</p></div><div class=product-return-actions><button class=link-btn onclick="setAllProductReturns(true)">全选</button><button class=link-btn onclick="setAllProductReturns(false)">全不选</button><span class=dash-pill>有效纳入 ${total.valid} / 已勾选 ${total.selected}</span></div></div><div class=product-return-wrap><table class=product-return-table><thead><tr><th class=select-col>选择</th><th class=product-col>产品</th><th>实际计算区间 / 状态</th><th>当前投资额</th><th>期初资产</th><th>申购</th><th>赎回</th><th>现金分红</th><th>期末资产</th><th>区间收益</th><th>日均占用资金</th><th>占用资金收益率</th><th>XIRR年化</th></tr></thead><tbody>${items.map(x=>{const p=x.calculated,ok=p&&p.status==='ok',usage=ok?productCapitalUsage(x.raw,p):null,checked=productReturnSelection.has(x.raw.name),status=ok?`${p.first.valuation_date} → ${p.last.valuation_date}<div class="sub ${p.boundary_complete?'':'negative'}">${p.boundary_complete?'边界完整':'边界不完整，使用实际估值日'}</div>`:`<span class=negative>${escapeHtml((p&&p.message)||'无法计算')}</span>`;return`<tr class=${checked?'':'product-return-unchecked'}><td class=select-col><input type=checkbox aria-label="选择${escapeHtml(x.raw.name)}" ${checked?'checked':''} onchange="setProductReturnChecked(${x.index},this.checked)"></td><td class=product-col><button class=product-return-link onclick="openProductReturn(${x.index})">${escapeHtml(x.raw.name)}</button></td><td>${status}</td><td>${money(x.raw.total_investment)}</td><td>${ok?money(p.first.net_assets):dash}</td><td>${ok?money(p.subscriptions):dash}</td><td>${ok?money(p.redemptions):dash}</td><td>${ok?money(p.dividendAmount):dash}</td><td>${ok?money(p.last.net_assets):dash}</td><td class=${ok?cls(p.profit):''}>${ok?money(p.profit):dash}</td><td>${usage?money(usage.average):dash}</td><td class=${usage?cls(usage.rate):''}>${usage?pct(usage.rate):dash}</td><td class=${ok?cls(p.annualized):''}>${ok?pct(p.annualized):dash}</td></tr>`}).join('')}</tbody><tfoot><tr><td class=select-col></td><td class=product-col><b>勾选产品合计</b><div class=sub>有效纳入 ${total.valid} / 已勾选 ${total.selected}</div></td><td>${total.valid?'合并有效产品实际现金流':dash}</td><td>${cell(total.investment)}</td><td>${cell(total.opening)}</td><td>${cell(total.subscriptions)}</td><td>${cell(total.redemptions)}</td><td>${cell(total.dividends)}</td><td>${cell(total.ending)}</td><td class=${cls(total.profit)}>${cell(total.profit)}</td><td>${cell(total.average)}</td><td class=${cls(total.capital_rate)}>${cell(total.capital_rate,'pct')}</td><td class=${cls(total.annualized)}>${total.annualized==null?dash:pct(total.annualized*100)}</td></tr></tfoot></table></div><p class=sub>日均占用资金按台账本金余额逐自然日计算，现金流发生日即改变余额；组合XIRR合并所选有效产品的实际日期现金流重新求解，不平均单只产品收益率。无法计算的勾选项保留展示但不进入合计。</p>`}
function productReturnTableStyles(){const s=document.createElement('style');s.textContent='.product-return-card{margin-bottom:16px}.product-return-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}.product-return-wrap{max-width:100%;overflow:auto;border:1px solid #e0e7ef;border-radius:12px}.product-return-table{min-width:1780px;border-collapse:separate;border-spacing:0}.product-return-table th{position:sticky;top:0;z-index:3;background:#173b6c;color:#fff}.product-return-table .select-col{position:sticky;left:0;width:58px;min-width:58px;text-align:center;z-index:4;background:inherit}.product-return-table .product-col{position:sticky;left:58px;width:270px;min-width:270px;z-index:2;background:inherit}.product-return-table tbody .select-col,.product-return-table tbody .product-col{background:#fff}.product-return-table tfoot td{background:#edf4fb;font-weight:600;border-top:2px solid #9eb4ca}.product-return-table tfoot .select-col,.product-return-table tfoot .product-col{background:#edf4fb}.product-return-unchecked{opacity:.48}.product-return-link{padding:0;background:transparent;color:#173b6c;text-align:left;font-weight:700}.product-return-link:hover{color:var(--green);text-decoration:underline}';document.head.appendChild(s)}
function documentProductReturnFormulaChange(){const cards=document.querySelectorAll('.info-card'),method=cards[0]&&cards[0].querySelector('.info-body');if(method)method.insertAdjacentHTML('beforeend','<p><b>FOF产品收益表公式：</b>每日本金余额 B(t)=截至t日累计申购−累计赎回；日均占用资金 A=ΣB(t)/实际区间自然日数，现金流发生日生效；占用资金收益率=区间收益/A，单位为%且不年化。组合A以所选产品资本占用日之和除以实际区间覆盖的自然日并集；组合XIRR合并期初资产、逐笔申购赎回、分红和期末资产的实际日期现金流后重新求解。金额单位为人民币元；样本要求产品收益状态可计算且实际起止日有效，否则保留缺失原因但不进入合计。</p>')}
function documentProductReturnTableChange(){const cards=document.querySelectorAll('.info-card'),method=cards[0]&&cards[0].querySelector('.info-body'),history=cards[2]&&cards[2].querySelector('.info-body');if(method)method.insertAdjacentHTML('beforeend','<p><b>FOF产品收益计算：</b>投资总览逐行列示当前范围内的顶层FOF，默认全选；勾选仅改变本表合计。日均占用资金按台账本金余额逐自然日加权，现金流发生日生效；占用资金收益率＝区间收益÷日均占用资金，不年化。组合XIRR合并所选有效产品的期初资产、逐笔申赎、分红和期末资产后重新求解。无法计算项保留但不进入合计，砚博等底层不重复列示。</p>');if(history)history.insertAdjacentHTML('afterbegin','<div class="history-item"><b>2026-09-08 · 本次更新</b><br>投资总览新增可勾选的顶层FOF收益计算表，逐项展示资产、现金流、收益、日均本金占用收益率和XIRR；默认全选，组合汇总不联动其他页面。</div>')}
function downloadMonthlyReport(){const input=document.getElementById('monthlyReportDate'),value=input&&input.value;if(!/^\d{4}-\d{2}-\d{2}$/.test(value||'')){alert('请选择有效截止日');return}location.href='/api/monthly-report?as_of='+encodeURIComponent(value)}
