function documentMonthlyReportChange(){const cards=document.querySelectorAll('.info-card'),method=cards[0]&&cards[0].querySelector('.info-body'),history=cards[2]&&cards[2].querySelector('.info-body');if(method)method.insertAdjacentHTML('beforeend','<p><b>报告出具与FOF1拆分：</b>投资总览可按截止日生成Excel月报。FOF1全委组合按10只顶层FOF汇总；专户和策略穿透天玑13号、盛乾同行2号、源泉优享FOF3号的截止日在投持仓，形式为专户的归专户，其余归策略，砚博除外。底层按FOF持仓分别计数，金额取实际市值和成本；“可计算”还要求所属FOF满足所选区间边界且底层收益可归属，分母仍为截止日在投持仓数。未穿透净资产差额单列且不强行分摊。</p>');if(history)history.insertAdjacentHTML('afterbegin','<div class="history-item"><b>2026-08-27 · 本次更新</b><br>修正FOF1穿透子组合的可计算数量：所属FOF边界不完整时，其底层不再错误计入可计算分子。</div><div class="history-item"><b>2026-08-27 · 本次更新</b><br>修正FOF1组合口径：全委扩展为含聚智多策略9号、嘉盈1号在内的10只顶层FOF；专户与策略改按三只FOF的在投底层及“形式”标签动态穿透，新增未穿透净资产差额。</div><div class="history-item"><b>2026-08-27 · 本次更新</b><br>投资总览新增按截止日生成并下载FOF月报；FOF1证投组新增专户、策略和全委三类组合汇总。</div>')}
