function strategyChartStyles(){const s=document.createElement('style');s.textContent='.strategy-chart-grid{display:grid;grid-template-columns:minmax(360px,.9fr) minmax(480px,1.25fr);gap:16px;margin:13px 0 17px}.strategy-chart-card{min-width:0;padding:15px 16px 10px;background:linear-gradient(145deg,#fff,#f8fafc);border:1px solid #dfe6ee;border-radius:16px;box-shadow:0 8px 24px #263b5209}.strategy-chart-title{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:3px}.strategy-chart-title b{font-size:14px;color:#263548}.strategy-chart-title span{font-size:11px;color:#8290a1}.strategy-chart-card canvas{height:300px;border:0;border-radius:0;background:transparent}@media(max-width:1050px){.strategy-chart-grid{grid-template-columns:1fr}.strategy-chart-card canvas{height:290px}}@media(max-width:600px){.strategy-chart-grid{display:block}.strategy-chart-card{margin-bottom:12px;overflow:auto}.strategy-chart-card canvas{min-width:500px}}';document.head.appendChild(s)}
function lookthroughGroupRow(group,end){const rows=[];FOF1_SPECIAL.forEach(name=>{const raw=RAW.products.find(p=>p.name===name),calculated=report.find(p=>p.name===name&&p.status==='ok'),point=raw&&before(raw.points,end),parentComplete=!!(calculated&&calculated.boundary_complete),periods=new Map(((calculated&&calculated.holdings)||[]).map(h=>[h.code,h]));(point&&point.holdings||[]).forEach(h=>{if(h.name===YANBO)return;const label=holdingLabel(h),isSpecial=label.vehicle==='专户';if((group.lookthrough==='专户')!==isSpecial)return;const period=periods.get(h.code);rows.push({fof:name,holding:h,period:period,parent_complete:parentComplete})})});return{name:group.name,level:group.level||0,lookthrough:true,ending:rows.reduce((s,x)=>s+(Number(x.holding.market_value)||0),0),profit:rows.reduce((s,x)=>s+(x.parent_complete&&x.period&&Number.isFinite(Number(x.period.period_profit))?Number(x.period.period_profit):0),0),calculated:rows.filter(x=>x.parent_complete&&x.period&&Number.isFinite(Number(x.period.period_profit))).length,total:rows.length,investment:rows.reduce((s,x)=>s+(Number(x.holding.cost)||0),0),positions:rows}}
function portfolioGroupRows(end){const owner=RAW.products.find(p=>p.name===TIANJI),ownerReport=report.find(p=>p.name===TIANJI&&p.status==='ok'),endPoint=owner&&before(owner.points,end),endHolding=endPoint&&(endPoint.holdings||[]).find(h=>h.name===YANBO),periodHolding=ownerReport&&(ownerReport.holdings||[]).find(h=>h.name===YANBO),rows=GROUPS.map(g=>{if(g.lookthrough)return lookthroughGroupRow(g,end);const products=RAW.products.filter(g.test),eligible=products.filter(p=>p.points&&p.points.length&&p.points[0].valuation_date<=end),names=new Set(products.map(p=>p.name)),valid=report.filter(x=>x.status==='ok'&&names.has(x.name)),complete=valid.filter(x=>x.boundary_complete);let ending=products.map(p=>before(p.points,end)).filter(Boolean).reduce((s,p)=>s+p.net_assets,0),profit=valid.reduce((s,p)=>s+p.profit,0),investment=products.reduce((s,p)=>s+(p.total_investment||0),0);if(g.exclude_holding){ending-=endHolding?endHolding.market_value||0:0;profit-=periodHolding?periodHolding.period_profit||0:0;investment-=endHolding?endHolding.cost||0:0}if(g.include_holding){ending+=endHolding?endHolding.market_value||0:0;profit+=periodHolding?periodHolding.period_profit||0:0;investment+=endHolding?endHolding.cost||0:0}return{name:g.name,level:g.level||0,ending,profit,calculated:complete.length+(g.include_holding&&periodHolding?1:0),total:eligible.length+(g.include_holding&&endHolding?1:0),investment}}),fullIndex=rows.findIndex(x=>x.name==='全委组合');rows.splice(fullIndex+1,0,{name:'未穿透差额（现金及净应收应付）',level:2,residual:true,ending:groupResidual(rows),profit:null,calculated:null,total:null,investment:null});return rows}
function groupResidual(rows){const get=name=>rows.find(x=>x.name===name)||{ending:0},fof1=get('FOF1证投组'),special=get('专户组合'),strategy=get('策略组合'),full=get('全委组合');return fof1.ending-special.ending-strategy.ending-full.ending}
function groupReportRows(){return portfolioGroupRows(endDate.value)}

function installStrategyTaskPolling(){document.addEventListener('click',function(event){const button=event.target.closest&&event.target.closest('#labRegenerate');if(!button)return;event.preventDefault();event.stopImmediatePropagation();button.disabled=true;button.textContent='任务运行中…';fetch('/api/strategy-lab/regenerate',{method:'POST'}).then(response=>{if(!response.ok)throw new Error('HTTP '+response.status);return response.json()}).then(task=>new Promise((resolve,reject)=>{const poll=()=>fetch(task.poll).then(response=>response.json()).then(state=>{if(state.status==='running'){setTimeout(poll,2500);return}if(state.status!=='ok'){reject(new Error(state.error||'重算失败'));return}resolve()}).catch(reject);poll()})).then(()=>loadDeferredModule('strategy-lab',true)).then(()=>renderStrategyLab()).catch(error=>{button.disabled=false;button.textContent='重新生成结果';alert('重算失败：'+error.message)})},true)}
installStrategyTaskPolling();
